import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderServiceTest {

    // 2026-10-31 12:00 Warsaw (CET, UTC+1) is 11:00 UTC; the cutoff is 2026-10-01 in Warsaw.
    private static final Instant NOW = Instant.parse("2026-10-31T11:00:00Z");

    private final OrderRepository repository = new OrderRepository();
    private final OrderService service = new OrderService(repository, Clock.fixed(NOW, ZoneOffset.UTC));

    @Test
    void expireStaleCancelsOnlyPlacedOrdersOlderThanThirtyDays() {
        String old = service.place("c", Money.pln(100), Instant.parse("2026-09-15T10:00:00Z"));
        String boundary = service.place("c", Money.pln(100), Instant.parse("2026-10-01T10:00:00Z"));
        String recent = service.place("c", Money.pln(100), Instant.parse("2026-10-10T10:00:00Z"));
        String oldConfirmed = service.place("c", Money.pln(100), Instant.parse("2026-09-01T10:00:00Z"));
        service.confirm(oldConfirmed);
        String oldCancelled = service.place("c", Money.pln(100), Instant.parse("2026-09-02T10:00:00Z"));
        service.cancel(oldCancelled);

        int cancelled = service.expireStale();

        assertEquals(1, cancelled);
        assertEquals("CANCELLED", service.summary(old).status());
        assertEquals("PLACED", service.summary(boundary).status());
        assertEquals("PLACED", service.summary(recent).status());
        assertEquals("CONFIRMED", service.summary(oldConfirmed).status());
        assertEquals("CANCELLED", service.summary(oldCancelled).status());
    }

    @Test
    void expireStaleUsesTheWarsawDayNotUtc() {
        // Placed 2026-09-30 23:30 Warsaw (CEST, 21:30 UTC) is on Sep 30 in Warsaw.
        // With the clock at 2026-10-31 00:30 UTC (01:30 Warsaw) the cutoff is Oct 1 in Warsaw, so Sep 30 is stale.
        OrderService atMidnightUtc = new OrderService(repository,
                Clock.fixed(Instant.parse("2026-10-31T00:30:00Z"), ZoneOffset.UTC));
        String order = atMidnightUtc.place("c", Money.pln(100), Instant.parse("2026-09-30T21:30:00Z"));

        assertEquals(1, atMidnightUtc.expireStale());
        assertEquals("CANCELLED", atMidnightUtc.summary(order).status());
    }

    @Test
    void expireStaleReturnsZeroWhenNothingIsStale() {
        service.place("c", Money.pln(100), Instant.parse("2026-10-30T10:00:00Z"));

        assertEquals(0, service.expireStale());
    }
}
}

